"use client";

import { Calendar, Clock, Sparkles, Users } from "lucide-react";
import type { FormatType, GameCardData, ResolutionType, ThemeType } from "@/lib/types";
import { getCanvasSize } from "@/lib/types";
import { themeClasses } from "./templateStyles";

export function GameCardTemplate({
  data,
  format,
  theme,
  resolution,
}: {
  data: GameCardData;
  format: FormatType;
  theme: ThemeType;
  resolution: ResolutionType;
}) {
  const size = getCanvasSize(format, resolution);
  const t = themeClasses(theme);
  const vertical = format === "vertical";

  return (
    <div style={{ width: size.width, height: size.height }} className={`asset-safe relative overflow-hidden ${t.bg}`}>
      <div className="absolute inset-0 bg-[linear-gradient(115deg,rgba(0,0,0,.34),transparent_48%,rgba(0,0,0,.22)),radial-gradient(circle_at_18%_16%,rgba(249,115,22,.32),transparent_30%),radial-gradient(circle_at_86%_22%,rgba(45,212,191,.22),transparent_28%)]" />
      <div className="absolute inset-x-16 top-14 h-2 rounded-full bg-gradient-to-r from-orange-400 via-amber-200 to-teal-300" />
      <div className={`relative grid h-full gap-14 p-20 pt-24 ${vertical ? "grid-rows-[auto_1fr_auto]" : "grid-cols-[1fr_820px]"}`}>
        <section className="flex min-h-0 flex-col justify-between">
          <div>
            <p className={`mb-7 inline-flex rounded-md px-6 py-3 text-3xl font-black uppercase ${t.accent}`}>Ficha técnica</p>
            <h1 className={`${vertical ? "text-8xl" : "text-[126px]"} max-w-[1000px] text-balance font-black leading-[0.9] drop-shadow-[0_8px_18px_rgba(0,0,0,.35)]`}>
              {data.gameName || "Nombre del juego"}
            </h1>
            <p className={`mt-8 text-4xl font-bold ${t.muted}`}>{data.publisher || "Editorial"} · {data.year || "Año"}</p>
          </div>

          <div className="space-y-5">
            <div className={`grid gap-5 ${vertical ? "grid-cols-2" : "grid-cols-3"}`}>
              <Info icon={Users} label="Jugadores" value={data.players || "2-4"} />
              <Info icon={Clock} label="Duración" value={data.duration || "45 min"} />
              <Info icon={Calendar} label="Edad" value={data.age || "10+"} />
            </div>
            <Info icon={Sparkles} label="Tipo / categorías" value={data.categories || "Familiar"} wide />
          </div>

          <div className={`rounded-lg border p-7 ${t.panel}`}>
            <div className="mb-5 flex items-center justify-between">
              <span className="text-3xl font-black uppercase text-white/90">Dificultad</span>
              <span className="rounded-md bg-black/25 px-5 py-2 text-4xl font-black">{data.difficulty}/5</span>
            </div>
            <div className="grid grid-cols-10 gap-3">
              {Array.from({ length: 10 }).map((_, index) => (
                <div key={index} className={`h-9 rounded-full ${index < data.difficulty * 2 ? "bg-gradient-to-r from-orange-300 to-orange-500" : t.line}`} />
              ))}
            </div>
          </div>
        </section>

        <section className="flex min-h-0 flex-col gap-8">
          <div className={`relative min-h-0 flex-1 overflow-hidden rounded-lg border-2 ${t.panel}`}>
            {data.coverImage ? (
              // eslint-disable-next-line @next/next/no-img-element
              <img src={data.coverImage} alt="" className="h-full w-full object-cover" />
            ) : (
              <div className="grid h-full place-items-center bg-[linear-gradient(145deg,rgba(20,184,166,.22),rgba(249,115,22,.18))] p-12 text-center">
                <div>
                  <div className="mx-auto mb-8 grid size-56 place-items-center rounded-lg border border-white/20 bg-black/24 text-9xl font-black text-teal-100">M</div>
                  <p className={`text-5xl font-black ${t.muted}`}>Portada del juego</p>
                </div>
              </div>
            )}
            <div className="absolute inset-x-0 bottom-0 h-32 bg-gradient-to-t from-black/55 to-transparent" />
          </div>
          <div className={`rounded-lg border p-8 ${t.panel}`}>
            <p className={`text-3xl font-black uppercase ${t.muted}`}>¿Para quién es el juego?</p>
            <p className="mt-3 text-5xl font-black leading-tight text-pretty">{data.verdict || "Un cierre memorable para la reseña."}</p>
          </div>
        </section>
      </div>
    </div>
  );
}

function Info({
  icon: Icon,
  label,
  value,
  wide = false,
}: {
  icon: React.ComponentType<{ className?: string }>;
  label: string;
  value: string;
  wide?: boolean;
}) {
  return (
    <div className={`${wide ? "min-h-32" : "min-h-40"} rounded-lg border border-white/12 bg-black/28 p-5 shadow-[0_18px_44px_rgba(0,0,0,.24)]`}>
      <Icon className="mb-4 size-10 text-teal-200" />
      <p className="text-2xl font-bold uppercase text-zinc-300/90">{label}</p>
      <p className={`${wide ? "line-clamp-2 text-3xl" : "line-clamp-3 text-[26px]"} mt-1 break-words font-black leading-tight`}>{value}</p>
    </div>
  );
}
